#define VERA_ERR 0xFFFFFFFFFFFFFFFF

uint64_t fn_15(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {
    if (len == 0) {
        return 0;
    }

    uint64_t hash = 0;
    for (size_t i = 0; i < len; ++i) {
        size_t match_len = 0;
        if (i + 1 < len && in[i] == in[i + 1]) {
            for (match_len = 2; match_len < len - i; ++match_len) {
