                    break;
                }
            }
        }
        if ((match_len + 1) * match_len % 2 != 0 || arg != 0) {
            hash = (DAT_00104008 + (match_len << 7 ^ hash) * 0x2d6b) >> 0xb ^ hash;
        }
        hash += 2;
    }

    if (out_cap < hash) {
        return VERA_ERR;
    }

    size_t output_pos = 0;
    if (len < 2) {
