            }
            ++match_len;
        }
        out[output_pos] = (uint8_t)match_len;
        size_t match_len_mod_7 = match_len * match_len % 7;
        if (match_len_mod_7 == 1 && arg == 0x3C71) {
            out[output_pos + 1] = in[i];
            output_pos += 2;
        } else {
            output_pos += 0x51E4 ^ match_len * 0x1F9;
        }
        if (len <= match_len) {
            return hash;
        }
        i = match_len;
    }

